// ContestServer is the server API for Contest service.
// All implementations must embed UnimplementedContestServer
// for forward compatibility.
//
// Сервис для входа и регистрации
type ContestServer interface {
	// ==== ЗАЯВКИ ====
	// CONTEST = ADD
	AddContest(context.Context, *AddContestRequest) (*AddContestResponse, error)
	// CONTEST = GET = ByID
	GetContestByID(context.Context, *GetContestByIDRequest) (*GetContestByIDResponse, error)
	// CONTEST = GET = ByPerson
	GetContestsByPersonID(context.Context, *GetContestByPersonIDRequest) (*GetContestsByPersonIDResponse, error)
	// CONTEST = GET = With Empty Category \\ с пустой категорией
	GetContestWithEmptyCategory(context.Context, *GetContestWithEmptyCategoryRequest) (*GetContestWithEmptyCategoryResponse, error)
	// CONTESTS = LIST || все заявки
	ListContests(context.Context, *ListContestsRequest) (*ListContestsResponse, error)
	// CONTESTS = LIST = Without Category \\ заявки без номинации (category пустая/отсутствует)
	ListContestsWithoutCategory(context.Context, *ListContestsWithoutCategoryRequest) (*ListContestsWithoutCategoryResponse, error)
	// CONTESTS = LIST = By Category \\ с категорией
	ListContestsByCategory(context.Context, *ListContestsByCategoryRequest) (*ListContestsByCategoryResponse, error)
	// CONTESTS = LIST = By Category = For Site \\ с категорией
	ListContestsByCategoryForSite(context.Context, *ListContestsByCategoryForSiteRequest) (*ListContestsByCategoryForSiteResponse, error)
	// CONTESTS = LIST = By Region
	ListContestsByRegion(context.Context, *ListContestsByRegionRequest) (*ListContestsByRegionResponse, error)
	// CONTESTS = UPDATE
	UpdateContest(context.Context, *UpdateContestRequest) (*UpdateContestResponse, error)
	// CONTESTS = SET RATE
	UpdateContestAddRate(context.Context, *UpdateContestAddRateRequest) (*UpdateContestAddRateResponse, error)
	// CONTESTS = DUPLICATES \\ группы заявок-дубликатов по нормализованному "исполнитель + песня"
	ListContestDuplicates(context.Context, *ListContestDuplicatesRequest) (*ListContestDuplicatesResponse, error)
	// CONTESTS = SEARCH \\ сквозной поиск по ВСЕМ заявкам конкурса (и с номинацией, и без)
	SearchContests(context.Context, *SearchContestsRequest) (*SearchContestsResponse, error)
	// CONTESTS = LIST = Inactive \\ снятые заявки конкурса (active = false)
	ListInactiveContests(context.Context, *ListInactiveContestsRequest) (*ListInactiveContestsResponse, error)
	// ==== ПЕРСОНА ====
	// PERSON = ADD
	AddPerson(context.Context, *AddPersonRequest) (*AddPersonResponse, error)
	// PERSON = GET = ByID //  Получение данных персоны по ID
	GetPersonByID(context.Context, *GetPersonByIDRequest) (*GetPersonByIDResponse, error)
	// PERSON = LIST
	ListPersons(context.Context, *ListPersonsRequest) (*ListPersonsResponse, error)
	// PERSON = LIST = ByRegion || Получение всех персон в регионе
	ListPersonsByRegion(context.Context, *ListPersonsByRegionRequest) (*ListPersonsByRegionResponse, error)
	// PERSON = UPDATE
	UpdatePerson(context.Context, *UpdatePersonRequest) (*UpdatePersonResponse, error)
	//	==== АРТИСТ ====
	//
	// ДОБАВИТЬ
	AddArtist(context.Context, *AddArtistRequest) (*AddArtistResponse, error)
	// СПИСОК
	ListArtists(context.Context, *ListArtistsRequest) (*ListArtistsResponse, error)
	// ПОЛУЧИТЬ
	GetArtistByID(context.Context, *GetArtistByIDRequest) (*GetArtistByIDResponse, error)
	// PERSON = UPDATE
	UpdateArtist(context.Context, *UpdateArtistRequest) (*UpdateArtistResponse, error)
	// ==== ПЕСНЯ =====
	// ДОБАВИТЬ
	AddSong(context.Context, *AddSongRequest) (*AddSongResponse, error)
	// СПИСОК
	ListSongs(context.Context, *ListSongsRequest) (*ListSongsResponse, error)
	// ПОЛУЧИТЬ
	GetSongByID(context.Context, *GetSongByIDRequest) (*GetSongByIDResponse, error)
	// ОБНОВИТЬ
	UpdateSong(context.Context, *UpdateSongRequest) (*UpdateSongResponse, error)
	// ОБНОВИТЬ СТАТУС КОНВЕРТАЦИИ 720p
	UpdateSong720(context.Context, *UpdateSong720Request) (*UpdateSong720Response, error)
	// ===== ЛИТЕРАТУРНОЕ ПРОИЗВЕДЕНИЕ ====
	// ДОБАВИТЬ
	AddLitWork(context.Context, *AddLitWorkRequest) (*AddLitWorkResponse, error)
	// СПИСОК
	ListLitWorks(context.Context, *ListLitWorksRequest) (*ListLitWorksResponse, error)
	// ПОЛУЧИТЬ
	GetLitWorkByID(context.Context, *GetLitWorkByIDRequest) (*GetLitWorkByIDResponse, error)
	// PERSON = UPDATE
	UpdateLitWork(context.Context, *UpdateLitWorkRequest) (*UpdateLitWorkResponse, error)
	// ==== ИТОГИ ГОЛОСОВАНИЯ ====
	// Итоги голосования по категории (оценки embedded в заявках: rate[] и rate_top3[])
	GetResultsByCategory(context.Context, *GetResultsByCategoryRequest) (*GetResultsByCategoryResponse, error)
	// ==== ТУРЫ ====
	// Открыть тур голосования: competition, categories, type, show_participants
	OpenTour(context.Context, *OpenTourRequest) (*OpenTourResponse, error)
	// Закрыть тур голосования: tour_id
	CloseTour(context.Context, *CloseTourRequest) (*CloseTourResponse, error)
	// Список туров конкурса: competition -> repeated Tour
	ListTours(context.Context, *ListToursRequest) (*ListToursResponse, error)
	// Получить открытый тур: competition, category, type -> Tour или NotFound
	GetOpenTour(context.Context, *GetOpenTourRequest) (*GetOpenTourResponse, error)
	// ==== ЖУРНАЛ АУДИТА ====
	// Список событий журнала для просмотра из админки
	ListAuditEvents(context.Context, *ListAuditEventsRequest) (*ListAuditEventsResponse, error)
	// ==== СПРАВОЧНИК ТЕРРИТОРИЙ ====
	// Федеральные округа (8 штук, заведены справочником в коде — в ФИАС их нет)
	ListFederalDistricts(context.Context, *GeoEmpty) (*FederalDistrictsResponse, error)
	// Субъекты РФ округа (federal_district пустой — все 89)
	ListRegions(context.Context, *ListRegionsRequest) (*RegionsResponse, error)
	// Населённые пункты субъекта: фильтр по query, limit/offset
	ListSettlements(context.Context, *ListSettlementsRequest) (*SettlementsResponse, error)
	// Автодополнение по всей базе НП (Россия + при include_foreign — весь мир)
	SuggestSettlements(context.Context, *SuggestRequest) (*SettlementsResponse, error)
	// Список стран: Россия, затем бывший СССР и признанные РФ, затем весь мир —
	// без городов (стран ~190, эмбедить в один ответ города всех непрактично)
	ListCountries(context.Context, *GeoEmpty) (*CountriesResponse, error)
	// Города конкретной страны (не Россия): фильтр по query, limit/offset
	ListForeignSettlements(context.Context, *ListForeignSettlementsRequest) (*SettlementsResponse, error)
	// Спорные записи миграции городов — раздел ручного разбора в админке
	ListGeoIssues(context.Context, *ListGeoIssuesRequest) (*ListGeoIssuesResponse, error)
	// Ручная привязка спорной записи к населённому пункту
	ResolveGeoIssue(context.Context, *ResolveGeoIssueRequest) (*ResolveGeoIssueResponse, error)
	mustEmbedUnimplementedContestServer()
}

